// Fork of "Oasis - Acute Angles in Voronoi" by Chimel. https://shadertoy.com/view/lfyfW1
// Fork of "VB / Random Power Oscillations" by Chimel. https://shadertoy.com/view/l33cz7

//=====================================
// Image: Final pass
//=====================================
/*
   iChannel0 = Buffer A
   iChannel1 = Buffer B
   iChannel2 = Buffer C
*/

#define PARTICLE_GRID_SIZE 25
#define NUM_PARTICLES (PARTICLE_GRID_SIZE * PARTICLE_GRID_SIZE)

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 I = ivec2(fragCoord);
    vec2 R = iResolution.xy;
    vec2 uv = fragCoord / R;
    vec2 wpos = (uv*2.0 -1.0)* vec2(R.x/R.y, 1.0);

    // 1) Voronoi background color
    float voroID = texelFetch(iChannel1, I, 0).x;
    int cellIndex = int(floor(voroID * float(NUM_PARTICLES)));
    cellIndex = clamp(cellIndex, 0, NUM_PARTICLES-1);

    // read the angle => color
    int px = cellIndex % PARTICLE_GRID_SIZE;
    int py = cellIndex / PARTICLE_GRID_SIZE;
    float angleCount = texelFetch(iChannel1, ivec2(px,py), 0).y;
    int ac = clamp(int(angleCount), 0, 3);

    // map 0..3 => color
    vec3 palette[4] = vec3[](
        vec3(1.000,1.000,1.000),  // 0 => White
        vec3(0.000,0.569,1.000),  // 1 => Blue
        vec3(1.000,0.000,0.149),  // 2 => Red
        vec3(0.000,0.000,0.000)   // 3 => Black
    );
    vec3 color = palette[ac]; // background color

    // 2) Overdraw circles in (almost) black
    float pxW = 2.0 / R.y;
    for(int y=0; y<PARTICLE_GRID_SIZE; y++){
        for(int x=0; x<PARTICLE_GRID_SIZE; x++){
            // read pos from A
            vec4 stA = texelFetch(iChannel0, ivec2(x,y), 0);
            vec2 cPos = stA.xy;

            // read radius from C
            float rad = texelFetch(iChannel2, ivec2(x,y), 0).r;

            // distance to pixel
            float d = length(wpos - cPos);
            float circleMask = 1.0 - smoothstep(rad - pxW, rad + pxW, d);

            // half‐transparent "circle color"
            vec3 circleColor = vec3(0.0);  
            float alpha = 0.075;
            color = mix(color, circleColor, circleMask * alpha);
        }
    }

    //--------------------------------------------------
    // (2b) ADD: Mark each Voronoi centroid with a white dot
    //--------------------------------------------------
    // You can tweak dotRadius to make the dots bigger or smaller
    float dotRadius = 0.005;
    for(int y=0; y<PARTICLE_GRID_SIZE; y++){
        for(int x=0; x<PARTICLE_GRID_SIZE; x++){
            // read pos from A
            vec4 stA = texelFetch(iChannel0, ivec2(x,y), 0);
            vec2 cPos = stA.xy;

            float d = length(wpos - cPos);
            float dotMask = 1.0 - smoothstep(dotRadius - pxW, dotRadius + pxW, d);

            // Full-intensity white at the center
            vec3 dotColor = vec3(1.0);
            color = mix(color, dotColor, dotMask);
        }
    }
    //--------------------------------------------------

    // 3) Voronoi edges
    if(I.x>0 && I.x<int(R.x)-1 && I.y>0 && I.y<int(R.y)-1){
        float cID = texelFetch(iChannel1,I,0).x;
        float lID = texelFetch(iChannel1,I+ivec2(-1,0),0).x;
        float rID = texelFetch(iChannel1,I+ivec2( 1,0),0).x;
        float uID = texelFetch(iChannel1,I+ivec2(0,-1),0).x;
        float dID = texelFetch(iChannel1,I+ivec2(0, 1),0).x;
        bool edge = (abs(cID-lID)>1e-4) || (abs(cID-rID)>1e-4)
                  || (abs(cID-uID)>1e-4) || (abs(cID-dID)>1e-4);
        if(edge){
            color = mix(color, vec3(0.0), 0.4);
        }
    }

    fragColor = vec4(color,1.0);
}

//=====================================
// Buffer A: Particle Physics (Periodic Boundaries)
//=====================================
/*
   iChannel0 = Buffer A (self feedback)
   iChannel1 = Buffer C (radius)
*/

#define PARTICLE_GRID_SIZE 25
#define NUM_PARTICLES (PARTICLE_GRID_SIZE * PARTICLE_GRID_SIZE)

// minimal spacing for blue-noise
#define MIN_DIST 0.08
#define BASE_MASS 1.0

//---------------------------------
// replicate position
//---------------------------------
vec2 getWrappedPos(vec2 orig, int kx, int ky, float aspect)
{
    // cast kx,ky to float => no error
    return orig + vec2( float(kx)*(2.0*aspect), float(ky)*2.0 );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pix = ivec2(fragCoord);
    if(pix.x >= PARTICLE_GRID_SIZE || pix.y >= PARTICLE_GRID_SIZE){
        fragColor=vec4(0.0);
        return;
    }

    int index = pix.y*PARTICLE_GRID_SIZE + pix.x;
    if(index >= NUM_PARTICLES){
        fragColor=vec4(0.0);
        return;
    }

    //---------------------------------
    // 1) init or read old
    //---------------------------------
    vec2 pos, vel;
    if(iFrame == 0)
    {
        // Blue-noise approach
        uint seed = uint(index);
        bool placed = false;
        vec2 candidate = vec2(0.0);

        float aspect = iResolution.x/iResolution.y;
        for(int attempt=0; attempt<200; attempt++){
            float rx = pcg_hash(seed);
            float ry = pcg_hash(seed);
            candidate= vec2(
                (rx*2.0 -1.0)*aspect,
                ry*2.0 -1.0
            );
            placed=true;
            for(int j=0; j<index; j++){
                ivec2 op = ivec2(j%PARTICLE_GRID_SIZE, j/PARTICLE_GRID_SIZE);
                vec4 st = texelFetch(iChannel0, op,0);
                vec2 oPos = st.xy;
                float dist2= dot(candidate - oPos, candidate - oPos);
                if(dist2 < MIN_DIST*MIN_DIST){
                    placed=false; break;
                }
            }
            if(placed) break;
        }
        if(!placed) candidate= vec2(0.0);

        pos = candidate;
        vel = vec2(0.0);
    }
    else
    {
        // read old
        vec4 oldSt= texelFetch(iChannel0, pix,0);
        pos= oldSt.xy;
        vel= oldSt.zw;
    }

    //---------------------------------
    // 2) move + physical wrap
    //---------------------------------
    float dt=0.016;
    pos += vel*dt;

    float aspect = iResolution.x/iResolution.y;
    vec2 bounds = vec2(aspect,1.0);

    // wrap physically
    if(pos.x> bounds.x)  pos.x -= 2.0*bounds.x;
    if(pos.x< -bounds.x) pos.x += 2.0*bounds.x;
    if(pos.y> 1.0)       pos.y -= 2.0;
    if(pos.y< -1.0)      pos.y += 2.0;

    //---------------------------------
    // 3) collisions
    //---------------------------------
    vec2 nextPos = pos;
    vec2 nextVel = vel;
    float myRadius= texelFetch(iChannel1, pix,0).r;

    for(int oy=0; oy<PARTICLE_GRID_SIZE; oy++){
        for(int ox=0; ox<PARTICLE_GRID_SIZE; ox++){
            int oid= oy*PARTICLE_GRID_SIZE + ox;
            if(oid==index) continue;

            vec4 st2= texelFetch(iChannel0, ivec2(ox,oy),0);
            vec2 oPos= st2.xy;
            vec2 oVel= st2.zw;
            float oR = texelFetch(iChannel1, ivec2(ox,oy),0).r;

            // check 9 copies
            for(int kx=-1; kx<=1; kx++){
                for(int ky=-1; ky<=1; ky++){
                    vec2 wrapPos= getWrappedPos(oPos, kx, ky, aspect);
                    if(checkCircleCollide(nextPos, myRadius, wrapPos, oR)){
                        // minimal approach => adjust only nextVel
                        // for a symmetrical approach you'd do a second pass
                        vec2 tempVel= nextVel;
                        dynamicCircleCircleCollisionResponse(
                            tempVel, BASE_MASS, nextPos,
                            oVel, BASE_MASS, wrapPos,
                            wrapPos, wrapPos,
                            myRadius, oR
                        );
                        nextVel= tempVel;
                    }
                }
            }
        }
    }

    // friction
    float sp2= dot(nextVel,nextVel);
    if(sp2<1e-4) nextVel= vec2(0.0);
    else nextVel*=0.90;

    fragColor= vec4(nextPos, nextVel);
}

//=====================================
// Buffer B: Voronoi ID + acute angles (Periodic)
//=====================================
/*
   iChannel0 = Buffer A
*/

#define PARTICLE_GRID_SIZE 25
#define NUM_PARTICLES (PARTICLE_GRID_SIZE * PARTICLE_GRID_SIZE)

#define EPSILON 1e-5
#define NEAREST_COUNT 12

//---------------------------------
// read pos from Buffer A
//---------------------------------
vec2 getParticlePos(int i)
{
    int px= i % PARTICLE_GRID_SIZE;
    int py= i / PARTICLE_GRID_SIZE;
    vec4 st= texelFetch(iChannel0, ivec2(px,py), 0);
    return st.xy;
}

//---------------------------------
// replicate position
//---------------------------------
vec2 wrapPos(vec2 base, int kx, int ky, float aspect)
{
    return base + vec2(float(kx)*(2.0*aspect), float(ky)*2.0);
}

float getAngle(vec2 p1, vec2 p2, vec2 p3){
    vec2 v1 = normalize(p1 - p2);
    vec2 v2 = normalize(p3 - p2);
    return acos(clamp(dot(v1,v2), -1.0, 1.0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pix = ivec2(fragCoord);
    float aspect= iResolution.x/iResolution.y;

    // (A) top-left NxN => angle detection
    if(pix.x< PARTICLE_GRID_SIZE && pix.y< PARTICLE_GRID_SIZE)
    {
        int index= pix.y*PARTICLE_GRID_SIZE + pix.x;
        if(index>= NUM_PARTICLES){
            fragColor= vec4(0.,0.,0.,1.);
            return;
        }

        // the cell center
        vec2 center= getParticlePos(index);

        // gather NEAREST_COUNT from [0..NUM_PARTICLES-1], each with 9 copies
        float dists[NEAREST_COUNT];
        // store (which real neighbor, which kx, ky) or just store offset
        int   neighborIdx[NEAREST_COUNT];
        vec2  wrapOffset[NEAREST_COUNT];

        // init
        for(int i=0; i<NEAREST_COUNT; i++){
            dists[i]=1e10;
            neighborIdx[i]=0;
            wrapOffset[i]= vec2(0.);
        }

        // pick best NEAREST_COUNT
        for(int i=0; i< NUM_PARTICLES; i++){
            if(i==index) continue;
            vec2 basePos= getParticlePos(i);

            for(int kx=-1; kx<=1; kx++){
                for(int ky=-1; ky<=1; ky++){
                    vec2 wPos= wrapPos(basePos, kx, ky, aspect);
                    float d2= dot(wPos - center, wPos - center);
                    // insertion
                    for(int s=0; s<NEAREST_COUNT; s++){
                        if(d2< dists[s]){
                            // shift
                            for(int t= NEAREST_COUNT-1; t> s; t--){
                                dists[t]       = dists[t-1];
                                neighborIdx[t] = neighborIdx[t-1];
                                wrapOffset[t]  = wrapOffset[t-1];
                            }
                            dists[s]       = d2;
                            neighborIdx[s] = i;
                            wrapOffset[s]  = (wPos - getParticlePos(i)); 
                            break;
                        }
                    }
                }
            }
        }

        // Build polygon
        vec2 vertices[512];
        int vCount= 0;

        for(int i=0; i<NEAREST_COUNT; i++){
            // neighbor #1 data
            int n1= neighborIdx[i];
            vec2 n1base= getParticlePos(n1);
            vec2 p1= n1base + wrapOffset[i]; // actual wrapped position
            // for j in [i+1..NEAREST_COUNT]
            for(int j=i+1; j<NEAREST_COUNT; j++){
                int n2= neighborIdx[j];
                vec2 n2base= getParticlePos(n2);
                vec2 p2= n2base + wrapOffset[j];

                // intersection
                vec2 v1= p1 - center;
                vec2 v2= p2 - center;
                float crossv= v1.x*v2.y - v1.y*v2.x;
                if(abs(crossv)<EPSILON) continue;

                float dd1= dot(v1,v1);
                float dd2= dot(v2,v2);
                float denom= 2.0*crossv;
                vec2 inter= center + vec2(
                    (v2.y*dd1 - v1.y*dd2)/denom,
                    (v1.x*dd2 - v2.x*dd1)/denom
                );

                // check "closer than center" for all real+wrapped neighbors
                bool valid=true;
                for(int k=0; k<NUM_PARTICLES; k++){
                    if(k==index) continue;
                    vec2 kb= getParticlePos(k);
                    for(int kx=-1; kx<=1; kx++){
                        for(int ky=-1; ky<=1; ky++){
                            vec2 kp= wrapPos(kb, kx, ky, aspect);
                            float dC= distance(inter, center);
                            float dK= distance(inter, kp);
                            if(dK+EPSILON < dC){
                                valid=false; 
                                break;
                            }
                        }
                        if(!valid) break;
                    }
                    if(!valid) break;
                }
                if(valid && vCount<512){
                    vertices[vCount++]= inter;
                }
            }
        }

        // sort + count angles
        for(int i=0; i<vCount-1; i++){
            for(int j=i+1; j<vCount; j++){
                float a1= atan(vertices[i].y-center.y, vertices[i].x-center.x);
                float a2= atan(vertices[j].y-center.y, vertices[j].x-center.x);
                if(a2< a1){
                    vec2 tmp= vertices[i];
                    vertices[i]= vertices[j];
                    vertices[j]= tmp;
                }
            }
        }

        int acuteCount=0;
        if(vCount>=3){
            for(int i=0; i<vCount; i++){
                vec2 pPrev= vertices[(i+vCount-1)%vCount];
                vec2 pCur = vertices[i];
                vec2 pNext= vertices[(i+1)%vCount];
                float ang= getAngle(pPrev, pCur, pNext);
                if(ang<1.5708){
                    acuteCount++;
                }
            }
        }
        if(acuteCount>3) acuteCount=3;

        fragColor= vec4(0., float(acuteCount), 0., 1.);
        return;
    }

    // (B) distance field
    vec2 uv = fragCoord/iResolution.xy;
    vec2 wpos= (uv*2.0 -1.0)* vec2(aspect,1.0);

    float minDist=1e10;
    int minIdx=-1;

    for(int i=0; i<NUM_PARTICLES; i++){
        vec2 base= getParticlePos(i);
        for(int kx=-1; kx<=1; kx++){
            for(int ky=-1; ky<=1; ky++){
                vec2 p= wrapPos(base,kx,ky,aspect);
                float d2= dot(wpos-p, wpos-p);
                if(d2<minDist){
                    minDist=d2;
                    minIdx= i;
                }
            }
        }
    }
    float ID= float(minIdx)/float(NUM_PARTICLES);
    fragColor= vec4(ID, 0.,0.,1.);
}

//---------------------------------------------------
// Common: Shared Functions
//---------------------------------------------------

float pcg_hash(inout uint seed) {
    seed = seed * 1664525u + 1013904223u;
    seed ^= seed >> 16u;
    seed *= 2074839491u;
    seed ^= seed >> 16u;
    seed *= 1868893697u;
    return float(seed)/4294967295.0;
}

bool checkCircleCollide(vec2 c1, float r1, vec2 c2, float r2) {
    return dot(c1-c2,c1-c2) < (r1+r2)*(r1+r2);
}

void dynamicCircleCircleCollisionResponse(
    inout vec2 v1, float m1, vec2 x1,
    inout vec2 v2, float m2, vec2 x2,
    inout vec2 p1, inout vec2 p2,
    float r1, float r2
){
    vec2 n = normalize(x2 - x1);
    float relVel = dot(v1 - v2, n);
    float p = relVel / (m1 + m2);

    // softer collisions
    v1 -= p*m2*n * 0.2;
    v2 += p*m1*n * 0.2;

    float dist = distance(x1,x2);
    float overlap = (r1 + r2) - dist;
    if(overlap>0.0){
        vec2 fix = 0.5*overlap*n;
        // extra repulsion
        float repulsion = 0.1;
        v1 -= repulsion*n;
        v2 += repulsion*n;

        p1 -= fix;
        p2 += fix;
    }
}

//=====================================
// Buffer C: Radius Storage & Update
//=====================================
/*
   iChannel0 = Buffer C (self)
   iChannel1 = Buffer B (for angles)
*/

#define PARTICLE_GRID_SIZE 25
#define NUM_PARTICLES (PARTICLE_GRID_SIZE * PARTICLE_GRID_SIZE)

// We'll do the same incremental logic
// We'll define a "base" = 0.05, but each circle can start with random factor
// Then we clamp to [0.05*0.2, 0.05*5.0] => [0.01..0.25]

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pixel = ivec2(fragCoord);
    if(pixel.x >= PARTICLE_GRID_SIZE || pixel.y >= PARTICLE_GRID_SIZE){
        fragColor = vec4(0.0);
        return;
    }

    int index = pixel.y * PARTICLE_GRID_SIZE + pixel.x;
    if(index >= NUM_PARTICLES){
        fragColor = vec4(0.0);
        return;
    }

    float baseRadius = 0.05;
    float oldRadius;

    if(iFrame == 0) {
        // Initialize with random size in [0.02..0.08], say
        // or pick your own range
        uint seed = uint(index)*12345u;
        float r = pcg_hash(seed); // each call modifies 'seed'
        // let's do [0.02..0.08] as an example
        float initRadius = mix(0.02, 0.08, r);

        oldRadius = initRadius;
    }
    else {
        // read old radius
        oldRadius = texelFetch(iChannel0, pixel, 0).r;
    }

    // read acute angles from B => .y
    float acute = texelFetch(iChannel1, pixel, 0).y;

    // expansions/shrinks
    float newRadius = oldRadius;
    if     (acute < 0.5) { newRadius *= 1.02;  }  
    else if(acute <1.5)  { newRadius *= 1.01; }  
    else if(acute <2.5)  { newRadius *= 0.94; }  
    else                 { newRadius *= 0.98;  }

    // clamp to [0.05*0.2..0.05*5.0] => [0.01..0.25]
    float minR = baseRadius * 0.4;
    float maxR = baseRadius * 1.8;
    newRadius = clamp(newRadius, minR, maxR);

    fragColor = vec4(newRadius, 0.0, 0.0, 1.0);
}
